"""Practice controls for chapter 3. The displayed question and reference answer are source crops.

These controls are separately labelled practice aids; they never replace the printed question/key.
"""
from itertools import product, permutations

def single(prompt, choices, correct, h1, h2):
    return dict(kind='single',prompt=prompt,options=[dict(text=v,correct=i==correct) for i,v in enumerate(choices)],hint1=h1,hint2=h2)

def multi(prompt, good, bad, h1, h2):
    return dict(kind='multi',prompt=prompt,pick=len(good),options=[dict(text=v,correct=True) for v in good]+[dict(text=v,correct=False) for v in bad],hint1=h1,hint2=h2)

def match(prompt, labels, answers, choices, h1, h2, **kw):
    return dict(kind='match',prompt=prompt,pairs=[dict(left=l,right=r) for l,r in zip(labels,answers)],choices=choices,hint1=h1,hint2=h2,**kw)

def classify(prompt, words, categories, assignments, h1, h2):
    return dict(kind='classify',prompt=prompt,items=[dict(text=w,category=c) for w,c in zip(words,assignments)],categories=categories,hint1=h1,hint2=h2)

def order(prompt, items, h1, h2):
    return dict(kind='order',prompt=prompt,items=items,correctOrder=list(range(len(items))),hint1=h1,hint2=h2)

